  "anomalies": [
    {
      "category": "wrong_value",
      "components": ["C21"],
      "pins": ["C21.1", "C21.2"],
      "nets": ["+5V", "GND"],
      "observed": "C21 is connected as a +5V-to-GND decoupling capacitor, but its schematic/SPICE value is 10 n while its footprint, library part, description, PN, and LCSC fields all identify a 10 µF 16 V X5R 0805 capacitor.",
      "expected": "The component value should agree with the selected part metadata (10 µF), or the footprint/PN/description should be changed to a 10 nF part. A passive's reference, value, footprint, library part, and description should be mutually consistent.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(comp (ref \"C21\") (value \"10n\") (footprint \"Coert-Vonk:CAP X5R 10μF ±10 16V 0805 Murata GRM\") ... (field (name \"PN\") \"GRM21BR61C106KE15L\") ... (description \"10 µF ±10% 16V Ceramic Capacitor X5R 0805 (2012 Metric)\"))"
        },
        {
          "source": "spice",
          "quote": "C21 0 +5V 10n"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"2\") (name \"+5V\") ... (node (ref \"C21\") (pin \"2\") (pintype \"passive\")) ... (net (code \"76\") (name \"GND\") ... (node (ref \"C21\") (pin \"1\") (pintype \"passive\")))"
        }
      ],
      "impact": "If the 10 nF value is used for assembly, the +5V rail loses the intended 10 µF bypass/bulk capacitance, increasing noise on the rail feeding the ESP32 DevKit and the AZ1117 LDO. If the 10 µF PN is used, the schematic/SPICE value is wrong and does not represent the built board.",
      "confidence": 0.75
    }
  ],
  "summary": "Most connectivity and values match the specification, but C21's schematic/SPICE value (10 nF) contradicts its selected component metadata (10 µF), indicating a component-value anomaly on the +5V decoupling network."
}

